; ship_test.asm - Ship Test: Mine Storm's mothership crossing the screen from top to bottom while it shrinks, over and
; over - the same every pass. For Smooth motion's tests: a shape of many strokes that moves and changes size.
; Generated by make_ship_test.py (the ship's strokes: ship_strokes.json). Build: build_cart.sh ship_test "Ship Test"

Wait_Recal      equ $F192
Intensity_a     equ $F2AB
Moveto_d        equ $F312
Reset0Ref       equ $F354
Draw_Line_d     equ $F3DF
Scale           equ $C880
Ypos            equ $C881
Tick            equ $C882
SMAX            equ 72                  ; the ship's scale at the top
YTOP            equ 96                  ; where it starts (at scale $7F), and -YTOP where it ends

        org     $0000
        fcc     "g GCE 2026"
        fcb     $80
        fdb     $FD0D
        fcb     $F8,$50,$20,-$48
        fcc     "SHIP TEST"
        fcb     $80
        fcb     0

Start:
        lda     #SMAX
        sta     Scale
        lda     #YTOP
        sta     Ypos
        clr     Tick
Main:
        jsr     Wait_Recal
        lda     #$5F
        jsr     Intensity_a
        jsr     Reset0Ref
        lda     #$7F                    ; to the ship's place, at full scale
        sta     <$04
        lda     Ypos
        clrb
        jsr     Moveto_d
        lda     Scale                   ; the ship, at its scale
        sta     <$04
        ldx     #Ship
Next    lda     ,x+
        beq     Mv
        bmi     Dr
        bra     Step
Mv      lda     ,x+
        ldb     ,x+
        pshs    x
        jsr     Moveto_d
        puls    x
        bra     Next
Dr      lda     ,x+
        ldb     ,x+
        pshs    x
        jsr     Draw_Line_d
        puls    x
        bra     Next
Step    dec     Ypos                    ; a step down every frame, smaller every third
        inc     Tick
        lda     Tick
        cmpa    #3
        blo     Chk
        clr     Tick
        dec     Scale
Chk     lda     Ypos
        cmpa    #-YTOP
        bgt     Main
        bra     Start

Ship:                                   ; flag (0 move, $FF draw, 1 end), y, x
        fcb     0,26,0
